      for (var opID in group.ops) {
        var op = group.ops[opID];
        var t = template.compile(group.template);

        source += t({
          key: opID,
          id: typeID,
          op: op.code,
          type: type,
        });
      }

      model.items.push({
        id: typeID,
        type: type,
        source: source,
        head: fs.readFileSync(typeID + '.js', 'utf-8'),
      });
    }
  }

  return model;
}

